            chartType: 'candles', // 'candles', 'hollow', 'heikinashi', 'bars', 'line', 'area', 'baseline'
            
            // Background - TradingView dark pane
            backgroundColor: '#131722',
            backgroundStyle: 'Solid', // 'Solid' or 'Gradient'
            
